calls.statement:
WITH dup AS (
  SELECT receipt_id, line_no, count(*) AS n FROM fact_sales_line GROUP BY 1,2 HAVING count(*)>1
)
SELECT f.sale_date, f.store_key, f.channel_code, count(*) AS rows_, count(DISTINCT f.receipt_id) AS receipts, min(f.etl_loaded_at) AS min_load, max(f.etl_loaded_at) AS max_load, sum(f.net_amount) AS net
FROM fact_sales_line f JOIN dup USING (receipt_id, line_no)
GROUP BY ALL ORDER BY 1 LIMIT 60;
